insert into public.jyc_events
  (slug,title,event_type,short_description,full_description,start_at,end_at,venue,status,featured,pinned)
values
('student-induction-program-2026','Student Induction Program 2026','Induction & Orientation','The 2026 JIIT induction programme for new students across Sector 62 and Sector 128.','JIIT’s 2026 Student Induction Program introduced new students to academic life, campus facilities, mentoring, student support, sports, JYC and the wider campus community.','2026-07-14T03:30:00+00','2026-08-01T12:30:00+00','JIIT Noida · Sector 62 & Sector 128','past',true,false),
('jyc-orientation-2026','JYC Orientation 2026','JYC Orientation','JYC’s orientation session introducing freshers to the student-led club ecosystem.','As part of the 2026 induction programme, JYC conducted an orientation session introducing students to the JYC ecosystem, student hubs, participation pathways and campus activities.','2026-07-16T08:30:00+00','2026-07-16T10:30:00+00','JIIT Noida · Induction Programme','past',true,false),
('jyc-performances-auditions-2026','JYC Performances & Auditions 2026','Cultural · Auditions','JYC performances and hub auditions during the 2026 induction programme.','The official 2026 induction schedule includes JYC performances and auditions, giving new students an early route into the cultural and creative side of campus life.','2026-07-24T04:00:00+00','2026-07-24T05:30:00+00','JIIT Noida · Sector 62 Campus','past',false,false),
('jyc-function-2026','JYC Function 2026','JYC Function','The annual JYC function listed in JIIT’s academic calendar.','JIIT’s official academic calendar lists the JYC Function for 6–8 February 2026 as part of the institute’s student activity calendar.','2026-02-06T03:30:00+00','2026-02-08T12:30:00+00','JIIT Noida','past',false,false),
('ebullience-freshers-welcome-2026','Ebullience 2026 · Fresher’s Welcome','Fresher’s Fest','JYC’s fresher-focused welcome experience for the 2026–27 intake.','Ebullience is JIIT’s fresher welcome tradition and a major JYC-led campus experience. The 2026–27 JYC activity budget lists the 2026 edition for 14 August 2026.','2026-08-14T03:30:00+00','2026-08-14T12:30:00+00','JIIT Sector 128, Noida','past',true,false),
('innovate-4-0-2026','Innovate 4.0','Inter-Institute Hackathon','The 2026 Innovate hackathon listed in the JYC activity calendar.','Innovate 4.0 is listed in the 2026–27 JYC activity budget as an inter-institute hackathon scheduled for 18–19 September 2026.','2026-09-18T03:30:00+00','2026-09-19T12:30:00+00','JIIT Noida','past',false,false),
('intra-institute-sports-week-2026','Intra-Institute Sports Week 2026','Sports Week','Campus sports week listed in the 2026–27 JYC activity calendar.','The 2026–27 JYC activity budget lists the Intra-Institute Sports Week for 24–26 September 2026.','2026-09-24T03:30:00+00','2026-09-26T12:30:00+00','JIIT Noida','past',false,false),
('teachers-day-2026','Teacher’s Day 2026','Campus Celebration','Campus celebration listed in the 2026–27 JYC activity calendar.','Teacher’s Day is listed in the 2026–27 JYC activity budget for 5 September 2026.','2026-09-05T03:30:00+00','2026-09-05T12:30:00+00','JIIT Noida','past',false,false),
('nukkad-natak-competition-2026','Inter-Institute Nukkad Natak Competition 2026','Theatre · Social Impact','An inter-institute street-theatre competition listed in the 2026–27 JYC activity plan.','The 2026–27 JYC activity budget lists this competition for 16 October 2026.','2026-10-16T03:30:00+00','2026-10-16T12:30:00+00','JIIT Noida','under_review',false,false),
('ethnic-day-diwali-2026','Ethnic Day & Diwali Celebration 2026','Cultural Celebration · Fest','The campus cultural celebration listed for the 2026–27 JYC activity calendar.','The 2026–27 JYC activity budget lists Ethnic Day and Diwali Celebration for 24 October 2026.','2026-10-24T03:30:00+00','2026-10-24T12:30:00+00','JIIT Noida · Sector 128','under_review',true,true),
('inter-institute-sports-week-2027','Inter-Institute Sports Week 2027','Sports Week','The next inter-institute sports week listed in the 2026–27 JYC activity plan.','The 2026–27 JYC activity budget lists this event for 28–30 January 2027.','2027-01-28T03:30:00+00','2027-01-30T12:30:00+00','JIIT Noida','under_review',false,false),
('converge-2027','Converge 2027','Technical · Cultural · Sports Fest','The next annual JIIT technical-cultural-sports fest listed in the JYC activity plan.','The 2026–27 JYC activity budget lists Converge 2027 for 27–28 February 2027.','2027-02-27T03:30:00+00','2027-02-28T12:30:00+00','JIIT Sector 128, Noida','under_review',true,true),
('inter-institute-battle-of-bands-2027','Inter-Institute Battle of Bands 2027','Music Competition','An inter-institute music event listed in the 2026–27 JYC activity plan.','The 2026–27 JYC activity budget lists Battle of Bands for 12 March 2027.','2027-03-12T03:30:00+00','2027-03-12T12:30:00+00','JIIT Noida','under_review',false,false),
('inter-institute-stage-play-2027','Inter-Institute Stage Play 2027','Theatre Competition','An inter-institute stage-play event listed in the 2026–27 JYC activity plan.','The 2026–27 JYC activity budget lists Stage Play for 9–10 April 2027.','2027-04-09T03:30:00+00','2027-04-10T12:30:00+00','JIIT Noida','under_review',false,false),
('farewell-2027','Farewell 2027','Farewell · Campus Celebration','The 2027 farewell programme listed in the 2026–27 JYC activity plan.','The 2026–27 JYC activity budget lists Farewell for 8 May 2027.','2027-05-08T03:30:00+00','2027-05-08T12:30:00+00','JIIT Noida','under_review',false,false)
